const num = value => value === null || value === undefined || value === '' ? '—' : new Intl.NumberFormat('zh-CN',{maximumFractionDigits:2}).format(Number(value));
const compact = value => value == null ? '—' : Number(value)>=10000 ? `${num(Number(value)/10000)}万` : num(value);
const bjtDate = (value = new Date()) => new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(value));
const time = (value,short=false) => {if(!value)return '未记录';const d=new Date(value);if(Number.isNaN(d.getTime()))return '未记录';return new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',...(short?{}:{year:'numeric',second:'2-digit'}),hour:'2-digit',minute:'2-digit',hour12:false}).format(d)};
const duration = seconds => {if(seconds==null)return '未记录';const n=Number(seconds);if(n<60)return `${Math.round(n)} 秒`;if(n<3600)return `${Math.round(n/60)} 分钟`;const h=Math.floor(n/3600),m=Math.round((n%3600)/60);return m===60?`${h+1} 小时`:`${h} 小时${m?` ${m} 分钟`:''}`};
const localDateTime = value => {if(!value)return '';const d=new Date(value);if(Number.isNaN(d.getTime()))return '';return new Date(d.getTime()+8*3600000).toISOString().slice(0,16)};
const iso = value => value ? new Date(`${value}:00+08:00`).toISOString() : null;
